import 'package:flutter/services.dart';
import 'package:flutter_appauth/flutter_appauth.dart';

import '../config.dart';
import 'authenticator.dart';
import 'session.dart';

/// Keycloak (realm `meridian`, public client `meridian-customer-mobile`) through the system browser with AppAuth:
/// authorization code + PKCE (S256, generated by AppAuth), private-use URI scheme redirect (RFC 8252). The access
/// token stays in memory; only the refresh token is persisted (secure storage, behind biometrics).
class AppAuthAuthenticator implements Authenticator {
  AppAuthAuthenticator(this.config, [FlutterAppAuth? appAuth]) : _appAuth = appAuth ?? const FlutterAppAuth();

  final AppConfig config;
  final FlutterAppAuth _appAuth;
  static const _scopes = ['openid', 'profile'];

  Session _session(String? access, String? refresh, String? id, DateTime? exp) {
    if (access == null) throw StateError('The identity provider returned no access token');
    return Session.fromTokens(accessToken: access, refreshToken: refresh, idToken: id, expiresAt: exp);
  }

  Future<Session> _authorize(Map<String, String> extra, {List<String>? prompt}) async {
    try {
      final r = await _appAuth.authorizeAndExchangeCode(AuthorizationTokenRequest(
        config.clientId,
        config.redirectUrl,
        issuer: config.issuer,
        scopes: _scopes,
        additionalParameters: extra,
        promptValues: prompt,
        allowInsecureConnections: config.allowInsecureConnections,
      ));
      return _session(r.accessToken, r.refreshToken, r.idToken, r.accessTokenExpirationDateTime);
    } on FlutterAppAuthUserCancelledException {
      throw SignInCancelled();
    } on PlatformException catch (e) {
      if (e.code.contains('cancel')) throw SignInCancelled();
      rethrow;
    }
  }

  @override
  Future<Session> signIn({DevIdentity? dev}) => _authorize(const {});

  @override
  Future<Session> stepUp(Session current, StepUpChallenge challenge) async {
    final acr = challenge.acr ?? config.stepUpAcr;
    final maxAge = challenge.maxAge ?? config.stepUpServerMaxAge;
    final next = await _authorize({'acr_values': acr, 'max_age': '${maxAge.inSeconds}'});
    if (next.customerId != current.customerId) throw StateError('Signed in as a different customer');
    if ((int.tryParse(next.acr ?? '') ?? 0) < (int.tryParse(acr) ?? 2)) throw StepUpUnavailable();
    return next;
  }

  @override
  Future<Session> refresh(Session current) async {
    final r = await _appAuth.token(TokenRequest(
      config.clientId,
      config.redirectUrl,
      issuer: config.issuer,
      refreshToken: current.refreshToken,
      scopes: _scopes,
      allowInsecureConnections: config.allowInsecureConnections,
    ));
    return _session(r.accessToken, r.refreshToken ?? current.refreshToken, r.idToken ?? current.idToken,
        r.accessTokenExpirationDateTime);
  }

  @override
  Future<void> signOut(Session current) async {
    try {
      await _appAuth.endSession(EndSessionRequest(
        idTokenHint: current.idToken,
        postLogoutRedirectUrl: config.redirectUrl,
        issuer: config.issuer,
        allowInsecureConnections: config.allowInsecureConnections,
      ));
    } catch (_) {
      // Local sign-out still happens (tokens are dropped); the IdP session expires on its own.
    }
  }
}
